/* SPDX-License-Identifier: GPL-3.0-only */
/* BF-033: Random direction TIE preview must match the next committed random position. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "sequencer.h"
#include "tb3po.h"

static pattern_t patterns[NPAT];
static seq_t seq;
static int note_on, note_off, m_on, m_off, errors, total;

#define EXPECT(c,why) do { total++; if (!(c)) { errors++; fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__,__LINE__,why); } } while (0)

static int drum(void *ctx,int k,int v,float vel) { (void)ctx; (void)k; (void)v; (void)vel; return 1; }
/* BF-028 on nightly: bass_on is int (*)(...); return 1 = accept. */
static int bass_on(void *ctx,int b,int note,int accent,int slide,int vel) {
    (void)ctx; (void)note; (void)accent; (void)slide; (void)vel;
    if (b == 0) note_on++;
    return 1;
}
static void bass_off(void *ctx,int b) { (void)ctx; if (b == 0) note_off++; }
static void brk(void *ctx,int p,int bar,float len,int enable) {
    (void)ctx; (void)p; (void)bar; (void)len; (void)enable;
}
static void brk_stop(void *ctx) { (void)ctx; }
static void midi(void *ctx, uint8_t st,uint8_t n,uint8_t v) {
    (void)ctx; (void)n; (void)v;
    if ((st & 0xF0u)==0x90u && (st & 0x0Fu)==1u) m_on++;
    if ((st & 0xF0u)==0x80u && (st & 0x0Fu)==1u) m_off++;
}
static const seq_sink_t sink = {
    .drum=drum, .bass_on=bass_on, .bass_off=bass_off,
    .brk=brk, .brk_stop=brk_stop, .midi=midi
};

static void setup(uint8_t dir,uint8_t forward_gate,uint8_t actual_random_gate) {
    memset(patterns,0,sizeof(patterns));
    pattern_init(&patterns[0],33,44);
    seq_init(&seq,patterns);
    seq.send_clock=0;
    seq.send_notes=1;
    seq.t[TRK_BASS0].rng=2u; /* next xorshift32 %4 == 2 */
    bpart_t *b=&patterns[0].bass[0];
    b->len=4; b->dir=dir;
    for(int p=0;p<4;p++) {
        b->step[p].flags=G_REST;
        b->step[p].velocity=100;
        b->step[p].note=(uint8_t)(48+p);
    }
    b->step[0].flags=G_NOTE;
    b->step[1].flags=forward_gate;
    b->step[2].flags=actual_random_gate;
    b->step[3].flags=G_REST;
    note_on=note_off=m_on=m_off=0;
}

static void start_then_midpoint(void) {
    uint32_t L=seq_step_q8(&seq,RATE_16);
    seq_start(&seq);
    seq_advance(&seq,1,&sink);
    EXPECT(seq.t[TRK_BASS0].pos==0,"first step must be 0");
    EXPECT(note_on==1,"first NOTE sounds exactly once");
    EXPECT(m_on==1,"first NOTE emits one MIDI NoteOn");
    EXPECT(seq.t[TRK_BASS0].rng==2u,"RANDOM preview does not draw RNG");
    uint32_t mid = (L >> 9) + 2u; /* just past 50%-gate release */
    seq_advance(&seq,mid,&sink);
}

static void finish_next(void) {
    uint32_t L=seq_step_q8(&seq,RATE_16);
    uint32_t mid=(L >> 9)+2u;
    uint32_t remainder=(L>>8)-mid+4u;
    seq_advance(&seq,remainder,&sink);
    EXPECT(seq.t[TRK_BASS0].pos==2,"RANDOM next position agrees with preview (seed2->2)");
    EXPECT(seq.t[TRK_BASS0].rng!=2u,"real RANDOM step commits RNG once");
}

static void case_random_actual_tie(void) {
    setup(DIR_RANDOM,G_REST,G_TIE);
    start_then_midpoint();
    EXPECT(note_off==0,"RANDOM NOTE -> selected TIE holds note through midpoint");
    EXPECT(seq.t[TRK_BASS0].sounding==1,"selected TIE has uninterrupted local 303 gate");
    EXPECT(m_off==0,"selected TIE does not send premature external MIDI NoteOff");
    finish_next();
    EXPECT(note_on==1,"selected TIE does not retrigger local NOTE");
    EXPECT(m_on==1,"selected TIE does not retrigger MIDI NoteOn");
    EXPECT(seq.t[TRK_BASS0].sounding==1,"selected TIE still holds sound after next step");
}

static void case_random_actual_note_not_tie(void) {
    setup(DIR_RANDOM,G_TIE,G_NOTE);
    start_then_midpoint();
    EXPECT(note_off==1,"unselected forward TIE must not wrongly prolong a RANDOM NOTE");
    EXPECT(m_off==1,"unselected forward TIE must not prolong MIDI NOTE");
    finish_next();
    EXPECT(note_on==2,"new selected NOTE triggers normally");
    EXPECT(m_on==2,"new selected NOTE emits MIDI NoteOn normally");
}

static void case_forward_tie(void) {
    setup(DIR_FWD,G_TIE,G_REST);
    start_then_midpoint();
    EXPECT(note_off==0,"FORWARD NOTE -> TIE still holds at midpoint");
    EXPECT(m_off==0,"FORWARD NOTE -> TIE keeps external MIDI gate");
}

static void case_forward_rest(void) {
    setup(DIR_FWD,G_REST,G_TIE);
    start_then_midpoint();
    EXPECT(note_off==1,"FORWARD NOTE -> REST still ends at midpoint");
    EXPECT(m_off==1,"FORWARD NOTE -> REST sends one MIDI NoteOff");
}

int main(void) {
    case_random_actual_tie();
    case_random_actual_note_not_tie();
    case_forward_tie();
    case_forward_rest();
    fprintf(stderr,"BF033 real-linked behavior: %d/%d assertions, errors=%d\n",total-errors,total,errors);
    return errors ? 1 : 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* BREAK render callback-tail host proxy. Actual linked production breaks.c.
 * Observed host p99 and worst block durations are NOT device ISR/XRUN proof.
 * Synthetic ADPCM only. No firmware/controller/SDK/private samples included. */
#define _POSIX_C_SOURCE 200809L
#include <inttypes.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "firmware/src/dsp/breaks.h"

#define BLOCK 64u
#define MIN_BLOCKS 64u
#define MAX_BLOCKS 4096u
static uint32_t rng(uint32_t *p)
{
    uint32_t x = *p;
    x ^= x << 13; x ^= x >> 17; x ^= x << 5;
    return *p = x;
}
static uint64_t ns(void)
{
    struct timespec t;
    if (clock_gettime(CLOCK_MONOTONIC, &t)) { perror("clock_gettime"); exit(3); }
    return (uint64_t)t.tv_sec * UINT64_C(1000000000) + (uint64_t)t.tv_nsec;
}
static int cmp_ns(const void *a, const void *b)
{
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return (x > y) - (x < y);
}
static void run(uint32_t n, const uint8_t *data, const int reverse,
                const int rate, unsigned trial, unsigned blocks)
{
    breaks_t *b = calloc(1, sizeof(*b));
    uint64_t *durations = calloc(blocks, sizeof(*durations));
    if (!b || !durations) { fputs("allocation failed\n", stderr); exit(3); }
    brk_loop_t loop = {.adpcm = data, .nsamples = n, .rate = 22050, .bars = 2};
    breaks_init(b);
    breaks_set_loop(b, 0, &loop);
    if (!b->bank[0].valid) { fputs("break bank invalid\n", stderr); exit(1); }
    breaks_set(b, BRK_LEVEL, 127);
    breaks_set(b, BRK_PITCH, 12);
    if (reverse) breaks_live(b, 8, 1);
    float sp16 = (float)n / (32.0f * (float)rate);
    if (!(sp16 > 1.0f)) { fputs("bad playback setup\n", stderr); exit(3); }
    breaks_step(b, 0, 0, sp16, 1);
    uint64_t hash = UINT64_C(1469598103934665603), audible = 0;
    uint64_t sum = 0;
    float out[BLOCK];
    for (unsigned j = 0; j < blocks; ++j) {
        const uint64_t before = ns();
        breaks_render(b, out, (int)BLOCK);
        const uint64_t after = ns();
        durations[j] = after - before;
        sum += durations[j];
        for (unsigned i = 0; i < BLOCK; ++i) {
            uint32_t bits = 0;
            if (!isfinite(out[i]) || fabsf(out[i]) > 2.0f) {
                fprintf(stderr, "invalid PCM len=%" PRIu32 " rev=%d rate=%d block=%u frame=%u: %g\n",
                        n, reverse, rate, j, i, out[i]); exit(1);
            }
            audible += (out[i] != 0.0f);
            memcpy(&bits, &out[i], sizeof(bits));
            for (unsigned k = 0; k < sizeof(bits); ++k) {
                hash ^= (uint8_t)(bits >> (k * 8u));
                hash *= UINT64_C(1099511628211);
            }
        }
    }
    if (!audible) { fputs("unexpectedly silent renderer\n", stderr); exit(1); }
    if (reverse) breaks_live(b, 8, 0);
    breaks_stop(b); breaks_set_quiet(b, 1);
    for (int i=0;i<16;++i) breaks_render(b,out,(int)BLOCK);
    if (!breaks_silent(b)) { fputs("non-silent after stop\n", stderr); exit(1); }
    for (unsigned i=0;i<BLOCK;++i) if (out[i] != 0.0f) {
        fputs("nonzero after stop\n", stderr); exit(1);
    }
    qsort(durations, blocks, sizeof(*durations), cmp_ns);
    printf("n=%" PRIu32 " direction=%c rate=%d trial=%u blocks=%u frames=%u"
           " hash=%016" PRIx64 " audible=%" PRIu64 " p50=%" PRIu64
           " p95=%" PRIu64 " p99=%" PRIu64 " max=%" PRIu64
           " sum=%" PRIu64 " stopped_silent=1\n", n, reverse ? 'R' : 'F',
           rate, trial, blocks, blocks * BLOCK, hash, audible,
           durations[(blocks - 1u)/2u], durations[((blocks-1u)*95u)/100u],
           durations[((blocks-1u)*99u)/100u], durations[blocks - 1u], sum);
    free(durations); free(b);
}
int main(int argc, char **argv)
{
    if (argc != 3 || strcmp(argv[1], "--blocks") != 0) {
        fputs("usage: breaks_callback_tail_perf_test --blocks 64..4096\n", stderr);
        return 2;
    }
    char *end = NULL;
    unsigned long arg = strtoul(argv[2], &end, 10);
    if (!*argv[2] || *end || arg < MIN_BLOCKS || arg > MAX_BLOCKS) {
        fputs("blocks outside 64..4096\n", stderr);
        return 2;
    }
    unsigned blocks = (unsigned)arg;
    static const uint32_t lengths[] = {65535u, 2116800u};
    static const int rates[] = {1,4,16,32,64,128,256,512,1024,2048};
    for (unsigned l = 0; l < sizeof(lengths)/sizeof(lengths[0]); ++l) {
        uint32_t n = lengths[l], seed = UINT32_C(0x43a9d671) ^ n;
        uint8_t *data = malloc(((size_t)n + 1u)/2u);
        if (!data) { fputs("data allocation failed\n", stderr); return 3; }
        for (size_t i = 0; i < ((size_t)n + 1u)/2u; ++i) data[i]=(uint8_t)rng(&seed);
        for (int rev = 0;rev <= 1; ++rev) {
            for (unsigned r = 0; r < sizeof(rates)/sizeof(rates[0]); ++r) {
                if (((float)n / (32.0f * (float)rates[r])) <= 1.0f) continue;
                for (unsigned trial = 0; trial < 2; ++trial)
                    run(n, data, rev, rates[r], trial, blocks);
            }
        }
        free(data);
    }
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Actual renderer pixels; no replacement caption formatter. */
#define CHICAGO_PRESENTATION_NO_MAIN
#include "chicago_presentation_test.c"
static const char *out;
static const char *const physical[]={"","KNOB 5","KNOB 6","KNOBS 5-6","KNOB 7","KNOBS 5,7","KNOBS 6-7","KNOBS 5-7","KNOB 8","KNOBS 5,8","KNOBS 6,8","KNOBS 5-6,8","KNOBS 7-8","KNOBS 5,7-8","KNOBS 6-8","KNOBS 5-8"};
static const char *const logical[]={"","KNOB 1","KNOB 2","KNOBS 1-2","KNOB 3","KNOBS 1,3","KNOBS 2-3","KNOBS 1-3","KNOB 4","KNOBS 1,4","KNOBS 2,4","KNOBS 1-2,4","KNOBS 3-4","KNOBS 1,3-4","KNOBS 2-4","KNOBS 1-4"};
static void check_caption(const char *caption,const char *name)
{
    int page=cur_page(),r=page%4,night=night_fixture(),top=24+r*(night?67:50);
    char title[80];put_s(put_s(put_i(title,r+1),"  "),matrix_group(page));
    int sound=pg.r[page][0].kind==R_BENGINE,pending=engine_bass_preset_pending(bidx());
    CHECK(8+tw(&FONT_T,title)+8<=232-tw(&FONT_T,caption));
    sound_t before=proj.sound;int dirty=ui.dirty,sw=save_wait;
    pref_t refs[4];memcpy(refs,pg.r[page],sizeof refs);
    shot(out,name);
    CHECK(!memcmp(&before,&proj.sound,sizeof before));CHECK(!memcmp(refs,pg.r[page],sizeof refs));
    CHECK(cur_page()==page && ui.dirty==dirty && save_wait==sw);
    uint16_t label=night?RGB(224,235,214):C_BLACK;
    cv_begin(240,12,night?RGB(37,59,45):matrix_col());
    if(night)cv_rect(4,0,232,1,RGB(62,92,64));
    cv_text(8,0,&FONT_T,title,label);text_r(232,0,&FONT_T,caption,label);
    for(int y=0;y<11;y++)for(int x=8;x<232;x++)CHECK(fb[(top+y)*240+x]==cv_px[y*240+x]);
    int nav=tw(&FONT_T,UI_CAP_ARROWS)+18+tw(&FONT_T,"ROW");
    char range[12];put_i(put_s(put_i(range,page/4*4+1),"-"),page/4*4+4<pg.n?page/4*4+4:pg.n);
    expected_footer_bg(night);
    uint16_t gray=night?RGB(156,170,168):C_GRAY,hint=night?RGB(196,155,69):C_HI;
    if(sound && pending) {
        CHECK(7+tw(&FONT_T,UI_CAP_HOME ": CANCEL")+8+nav<=234);
        cv_text(7,0,&FONT_T,UI_CAP_HOME ": CANCEL",gray);expected_row_hint(234-nav,0,hint);
    } else {
        const char *right=sound?UI_CAP_HOME ": BACK":range;
        int x=expected_row_hint(7,0,gray);cv_text(x+8,0,&FONT_T,UI_CAP_EDIT ": NEXT",gray);
        CHECK(x+8+tw(&FONT_T,UI_CAP_EDIT ": NEXT")+8+tw(&FONT_T,right)<=234);
        text_r(234,0,&FONT_T,right,hint);
    }
    for(int y=0;y<12;y++)for(int x=0;x<240;x++)CHECK(fb[(228+y)*240+x]==cv_px[y*240+x]);
}
static void check_wrap(void)
{
    for(int v=0;v<2;v++)for(int bank=0;bank<2;bank++) {
        fixture(v,bank);int n=pg.n;CHECK(n==7);
        *page_of(V_PART)=0;
        for(int d=-1;d<=1;d+=2)for(int i=0;i<n*2;i++) {
            int previous=cur_page(),want=(previous+d+n)%n;
            sound_t before=proj.sound;int dirty=ui.dirty,sw=save_wait;
            now_ms++;enc_acc[EN_SELECT]=d;ui_input_only();
            CHECK(cur_page()==want);CHECK(cur_page()/4==want/4);
            CHECK(!memcmp(&before,&proj.sound,sizeof before));CHECK(ui.dirty==dirty && save_wait==sw);
            if(previous/4!=want/4) {
                unsigned mask=0;for(int k=0;k<4;k++)if(pg.r[want][k].kind!=R_NONE)mask|=1u<<k;
                char name[64];snprintf(name,sizeof name,"%s-%c-wrap-%d-%d",bank?"miami":"chicago",'a'+v,d,want+1);
                check_caption((X0X_SMK_CAPTIONS?physical:logical)[mask],name);
            }
        }
        /* Other views keep their previous clamp behavior. */
        set_view(V_SEQ);*page_of(V_SEQ)=0;now_ms++;enc_acc[EN_SELECT]=-1;ui_input_only();CHECK(cur_page()==0);
        *page_of(V_SEQ)=pg.n-1;now_ms++;enc_acc[EN_SELECT]=1;ui_input_only();CHECK(cur_page()==pg.n-1);
    }
}
int main(int argc,char **argv)
{
    CHECK(argc==2);out=argv[1];boot();run_ms(50);engine_guard_enable(0);
    check_wrap();if(getenv("X0X_CAPTION_WRAP_ONLY")){printf("PASS %u row wrap checks\n",checks);return 0;}
    const char *const *names=X0X_SMK_CAPTIONS?physical:logical;
    for(int v=0;v<2;v++)for(int bank=0;bank<2;bank++) {
        fixture(v,bank);
        CHECK(8+tw(&FONT_T,"3  SOUND")+8<=232-tw(&FONT_T,names[3]));
        for(int p=0;p<pg.n;p++) {
            *page_of(V_PART)=p;unsigned mask=0;char name[64];
            for(int k=0;k<4;k++)if(pg.r[p][k].kind!=R_NONE)mask|=1u<<k;
            snprintf(name,sizeof name,"%s-%c-row-%d",bank?"miami":"chicago",'a'+v,p+1);
            check_caption(names[mask],name);
        }
        /* Requested-engine name and pending actions are rendered, not inferred. */
        *page_of(V_PART)=row(R_BENGINE,0);request(v,bank^1);engine_bass_wheel_owners(1u<<v);
        check_caption(names[3],"pending-sound");engine_bass_cancel_preset(v);engine_bass_wheel_owners(0);
    }
    /* Exhaust every possible hole pattern without compacting the four slots. */
    fixture(0,0);*page_of(V_PART)=0;pref_t refs[4];memcpy(refs,pg.r[0],sizeof refs);
    for(int mask=0;mask<16;mask++) {
        for(int k=0;k<4;k++)pg.r[0][k]=(mask&(1<<k))?refs[k]:NONE;
        char name[32];snprintf(name,sizeof name,"mask-%02d",mask);check_caption(names[mask],name);
    }
    puts("Caption and footer tests use exact production framebuffer pixels.");
    printf("PASS %u mapped-knob caption checks; SMK captions=%d\n",checks,X0X_SMK_CAPTIONS);return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Linked production sequencer regression: a live 303 ping-pong length shrink
 * cannot step through positions outside the new range or mutate lookahead.
 * Compile against firmware/src/seq/{sequencer,pattern,tb3po}.c. */
#include <stdio.h>
#include "../../firmware/src/seq/sequencer.h"

static unsigned checks, failures;
#define CHECK(expr, what) do { checks++; if (!(expr)) { \
    failures++; if (failures <= 12u) printf("FAIL %s:%d %s\n", __FILE__, __LINE__, what); \
} } while (0)

static pattern_t patterns[NPAT];
static seq_t seq;
static unsigned observed_steps;
static int observed_last_step;
static unsigned note_on_count, note_off_count;

static void on_step(void *context, int track, int step)
{
    (void)context;
    if (track == TRK_BASS0) {
        observed_steps++;
        observed_last_step = step;
    }
}
static int on_bass(void *context, int part, int pitch, int accent, int slide, int velocity)
{
    (void)context; (void)part; (void)pitch; (void)accent; (void)slide; (void)velocity;
    note_on_count++;
 return 1; }
static void off_bass(void *context, int part)
{
    (void)context; (void)part;
    note_off_count++;
}
static const seq_sink_t sink = {
    .bass_on = on_bass, .bass_off = off_bass, .step = on_step
};

static void reset_seq(int length, int direction)
{
    for (int i=0; i<NPAT; i++) pattern_init(&patterns[i], (unsigned)(i+1), (unsigned)(i+101));
    seq_init(&seq, patterns);
    seq.send_clock = 0;
    patterns[0].bass[0].dir = DIR_PINGPONG;
    patterns[0].bass[0].len = (uint8_t)length;
    seq.t[TRK_BASS0].pp_dir = (int8_t)direction;
    observed_steps = 0;
    observed_last_step = -1;
    note_on_count = note_off_count = 0;
}

static void test_lookahead(void)
{
    static const int pvals[] = {0,1,2,3,4,5,7,15,31,63};
    for (int dir=-1; dir<=1; dir+=2) {
        reset_seq(4,dir);
        for (unsigned i=0; i<sizeof pvals/sizeof pvals[0]; i++) {
            int p=pvals[i];
            int got=seq_next_step(&seq, TRK_BASS0,p);
            CHECK(got>=0 && got<4, "lookahead within shortened 303 pattern");
            CHECK(seq.t[TRK_BASS0].pp_dir == dir, "lookahead preserves committed ping-pong direction");
            if (p>=4) CHECK(got==3, "out-of-range high position snaps to last valid step");
        }
    }
    reset_seq(4,1);
    CHECK(seq_next_step(&seq,TRK_BASS0,-1)==0, "negative lookahead index snaps to first step");
    CHECK(seq.t[TRK_BASS0].pp_dir==1, "negative lookahead cannot flip direction");
    reset_seq(1,1);
    CHECK(seq_next_step(&seq,TRK_BASS0,15)==0, "one-step pattern clamps old playhead");
    reset_seq(8,1);
    CHECK(seq_next_step(&seq,TRK_BASS0,3)==4, "expanding pattern preserves interior forward progression");
    reset_seq(4,-1);
    patterns[0].bass[0].dir=DIR_REV;
    CHECK(seq_next_step(&seq,TRK_BASS0,3)==2, "reverse mode unchanged");
    reset_seq(4,1);
    patterns[0].bass[0].dir=DIR_FWD;
    CHECK(seq_next_step(&seq,TRK_BASS0,3)==0, "forward mode unchanged");
}

static void test_committed_audio_step(void)
{
    for (int direction=-1; direction<=1; direction+=2) {
        reset_seq(16,direction);
        seq_start(&seq);
        seq_advance(&seq,0,&sink);
        CHECK(seq.playing, "transport started");
        patterns[0].bass[0].len=4;   /* user shortens while original step 16 is still current */
        seq.t[TRK_BASS0].started=1;
        seq.t[TRK_BASS0].pos=15;
        seq.t[TRK_BASS0].pp_dir=(int8_t)direction;
        seq.t[TRK_BASS0].to_next=0;
        unsigned prior=observed_steps;
        seq_advance(&seq,0,&sink);
        CHECK(seq.t[TRK_BASS0].pos==3, "committed next playback step is inside newly shortened pattern");
        CHECK(seq.t[TRK_BASS0].pp_dir==-1, "committed out-of-range correction points back inward");
        CHECK(observed_steps==prior+1, "next 303 step emitted exactly once");
        CHECK(observed_last_step==3, "UI step callback saw last enabled step, not removed step");
        seq.t[TRK_BASS0].to_next=0;
        seq_advance(&seq,0,&sink);
        CHECK(seq.t[TRK_BASS0].pos==2, "subsequent playback walks inward one step");
        CHECK(observed_last_step==2, "next UI callback sees inward step");
    }
}

static void test_shrink_matrix(void)
{
    for (int old_len=2; old_len<=64; old_len++) {
        for (int new_len=1; new_len<=old_len; new_len++) {
            reset_seq(new_len,1);
            for (int p=0; p<old_len; p++) {
                for (int dir=-1; dir<=1; dir+=2) {
                    seq.t[TRK_BASS0].pp_dir=(int8_t)dir;
                    int got=seq_next_step(&seq,TRK_BASS0,p);
                    CHECK(got>=0 && got<new_len, "entire shrink matrix lookahead in bounds");
                    CHECK(seq.t[TRK_BASS0].pp_dir==dir, "shrink matrix lookahead has no side effects");
                }
            }
        }
    }
}

int main(void)
{
    test_lookahead();
    test_committed_audio_step();
    test_shrink_matrix();
