/* SPDX-License-Identifier: GPL-3.0-only */
/* Public recognizer contract: arbitrary played notes, not the selected chord preset. */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#define CK_FN __attribute__((unused))
#define CK_CD_FN __attribute__((unused))
#include "app/smk_clip_keys.h"
#include "app/smk_chord_detect.h"

static unsigned checks;
static ck_chord_input_t input(const uint8_t *notes, unsigned count)
{
    ck_chord_input_t in = {0, 0, 255, 255};
    unsigned i;
    for (i = 0; i < count; i++)
        if (notes[i] < in.bass) in.bass = notes[i];
    for (i = 0; i < count; i++) {
        in.pcs |= 1u << (notes[i] % 12);
        if (notes[i] > in.bass) {
            in.upper_pcs |= 1u << (notes[i] % 12);
            if (notes[i] < in.upper_bass) in.upper_bass = notes[i];
        }
    }
    return in;
}
static void expect(const uint8_t *notes, unsigned count, const char *want)
{
    ck_chord_input_t in = input(notes, count);
    ck_chord_result_t r;
    char text[32];
    int found = ck_chord_detect(&in, &r);
    ck_chord_format(&r, text, sizeof text);
    checks++;
    if (strcmp(text, want)) {
        fprintf(stderr, "wanted %s, got %s (found %d, mask %03x)\n", want, text, found, in.pcs);
        assert(!strcmp(text, want));
    }
    assert(found == (strcmp(want, "-") != 0));
}
int main(void)
{
    static const char *const roots[] = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
    static const struct { uint8_t n[7]; unsigned count; const char *name; } cases[] = {
        {{60,64,67},3,"C"}, {{64,67,72},3,"C"}, {{55,60,64},3,"C"},
        {{60,63,67},3,"Cm"}, {{60,64,67,71},4,"Cmaj7"}, {{60,63,67,70},4,"Cm7"},
        {{60,64,67,70},4,"C7"}, {{60,62,67},3,"Csus2"}, {{60,65,67},3,"Csus4"},
        {{60,63,66,69},4,"Cdim7"}, {{60,64,68},3,"Caug"}, {{60,63,66},3,"Cdim"},
        {{60,64,67,69},4,"C6"}, {{57,60,64,67},4,"Am7"},
        {{50,60,64,67},4,"C/D"}, {{53,60,64,67},4,"C/F"},
        {{40,59,62,66},4,"Bm/E"}, {{60,64,67,74},4,"Cadd9"},
        {{60,64,67,70,74},5,"C9"}, {{60,64,70},3,"C7"},
        {{60,60,64,67,72},5,"C"}, {{60,61,62},3,"-"},
        {{60,64},2,"-"}, {{60,72},2,"-"}, {{60},1,"-"}, {{0},0,"-"}
    };
    unsigned i, root, inv;
    for (i = 0; i < sizeof cases / sizeof cases[0]; i++) expect(cases[i].n,cases[i].count,cases[i].name);
    for (root = 0; root < 12; root++) {
        char want[24];
        for (inv = 0; inv < 3; inv++) {
            uint8_t notes[6];
            for (i = 0; i < 3; i++) {
                static const uint8_t major[] = {0,4,7};
                notes[i] = 48 + root + major[i] + (i < inv ? 12 : 0);
                notes[i+3] = notes[i] + 12;
            }
            snprintf(want,sizeof want,"%s",roots[root]);
            expect(notes,6,want);
            for (i = 0; i < 6; i++) if (i % 3 == 1) notes[i]--;
            snprintf(want,sizeof want,"%sm",roots[root]);
            expect(notes,6,want);
        }
    }
    /* Every fixed generator shape remains recognizable, across keys and voicings.
     * Scale-stack modes are covered separately: unusual scales may form unnamed clusters. */
    for (i = 0; i < CK_NCHORD; i++) {
        if (i >= 14 && i <= 16) continue;
        for (root = 0; root < 12; root++) for (inv = 0; inv < 4; inv++) {
            uint8_t notes[CK_MAXN]; ck_chord_result_t r;
            unsigned n = ck_notes(48+root,ck_mask(0,0),0,i,inv,notes);
            ck_chord_input_t in = input(notes,n);
            if (!ck_chord_detect(&in,&r)) {
                fprintf(stderr,"unrecognized generator mode %u root %u inversion %u mask %03x\n",i,root,inv,in.pcs);
                assert(0);
            }
            checks++;
        }
    }
    for (root = 0; root < 12; root++) for (i = 0; i < CK_NSCALE; i++) for (inv = 14; inv <= 16; inv++) {
        uint8_t notes[CK_MAXN]; ck_chord_result_t r;
        unsigned n = ck_notes(48+root,ck_mask(i,root),0,inv,0,notes);
        ck_chord_input_t in = input(notes,n);
        char text[32];
        int found = ck_chord_detect(&in,&r);
        ck_chord_format(&r,text,sizeof text);
        assert(found || !strcmp(text,"-")); checks++;
    }
    {
        static const char *const names[] = {"C", "Cmaj7", "Cmaj9"};
        for (i=14;i<=16;i++) {
            uint8_t notes[CK_MAXN];
            unsigned n=ck_notes(48,ck_mask(0,0),0,i,0,notes);
            expect(notes,n,names[i-14]);
        }
    }
    /* All pitch-class inputs and every output capacity: no overwrite, always terminated. */
    for (i = 0; i < 4096; i++) {
        uint8_t notes[12]; unsigned n=0,pc,cap; ck_chord_result_t r;
        for (pc=0;pc<12;pc++) if (i >> pc & 1) notes[n++]=48+pc;
        ck_chord_input_t in=input(notes,n);
        ck_chord_detect(&in,&r);
        for(cap=0;cap<=24;cap++) {
            unsigned char bytes[26]; memset(bytes,0xa5,sizeof bytes);
            ck_chord_format(&r,(char*)bytes+1,cap);
            assert(bytes[0]==0xa5 && bytes[cap+1]==0xa5);
            assert(!cap || memchr(bytes+1,0,cap));
            checks++;
        }
    }
    printf("chord recognition: %u checks passed\n",checks);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Pure factory-AU bytes -> complete engine-owned product cell. No DSP/storage writes. */
#pragma once
#include "engine.h"
#include "factory_banks.h"
#include "chicago_env.h"
#include "chicago_arp.h"
#include "chicago_fx.h"
#include "chicago_aux.h"
#include "../dsp/wobble_config.h"

typedef const x0x_param_t *(*bass_preset_param_fn)(int bank, int param);
enum { BASS_PRESET_OK = 0, BASS_PRESET_INVALID = -1, BASS_PRESET_UNAVAILABLE = -2 };

static inline int bass_preset_decode_record(int bank, const factory_preset_t *p,
                                            bass_preset_param_fn param, uint8_t out[NPARAMS_MAX])
{
    static const uint8_t au_to_chicago[13] = {5,10,0,1,2,18,17,19,20,21,22,16,7};
    uint8_t values[NPARAMS_MAX] = {0};
    int count, required, i, name_end = 0;
    if (!p || !param || !out || (bank != FACTORY_BANK_CHICAGO && bank != FACTORY_BANK_MIAMI))
        return BASS_PRESET_INVALID;
    count = bank == FACTORY_BANK_CHICAGO ? CHI_AUX_END : WOBBLE_EXPERIMENT_NPARAMS;
    required = bank == FACTORY_BANK_CHICAGO ? FACTORY_CHICAGO_NPARAMS : FACTORY_MIAMI_NPARAMS;
    if (p->nparams != required || !p->name[0]) return BASS_PRESET_INVALID;
    for (i = 0; i < FACTORY_NAME_MAX; i++) name_end |= !p->name[i];
    if (!name_end || count > NPARAMS_MAX) return BASS_PRESET_INVALID;
    if (!param(bank,0)) return BASS_PRESET_UNAVAILABLE;
    if (param(bank,count)) return BASS_PRESET_INVALID; /* wrong backend surface */
    for (i = 0; i < count; i++) {
        const x0x_param_t *d = param(bank,i);
        if (!d || !d->name || d->def > d->max) return BASS_PRESET_INVALID;
        values[i] = d->def;
    }
    if (bank == FACTORY_BANK_MIAMI) {
        for (i = 0; i < required; i++)
            values[i] = chi_env_pot_from_byte(p->pots[i], param(bank,i)->max);
    } else {
        for (i = 0; i < 13; i++) {
            unsigned target = au_to_chicago[i];
            values[target] = chi_env_pot_from_byte(p->pots[i],param(bank,(int)target)->max);
        }
        chi_env_apply_factory_voice(values,p->pots+7);
        chi_arp_apply_factory_voice(values,p->pots+13);
        uint8_t fx[3]; chi_fx_decode_factory(p->pots+17,fx);
        for (i = 0; i < 3; i++) values[CHI_FX_TYPE+i]=fx[i];
        chi_aux_apply_factory_voice(values,p->pots+20);
    }
    for (i = 0; i < count; i++)
        if (values[i] > param(bank,i)->max) return BASS_PRESET_INVALID;
    /* Invalid/unavailable input leaves the caller's original cell unchanged. */
    for (i = 0; i < NPARAMS_MAX; i++) out[i]=values[i];
    return BASS_PRESET_OK;
}
static inline int bass_preset_decode(int bank, int index, bass_preset_param_fn param,
                                     uint8_t out[NPARAMS_MAX])
{
    return bass_preset_decode_record(bank,factory_preset(bank,index),param,out);
}

// SPDX-License-Identifier: GPL-3.0-only
// Host-only BF-001 regression: local .fwsc / ctl.img selection generations.
// No Web MIDI, no device write. Newest selection wins; stale completions no-op.
import { readFileSync } from 'node:fs';
import { runInNewContext } from 'node:vm';
import assert from 'node:assert/strict';

const html = readFileSync(process.env.X0X_INSTALLER_HTML || new URL('./x0x_installer.html', import.meta.url), 'utf8');
const start = html.indexOf('let stockLoadSerial = 0;');
const stop = html.indexOf('async function run(img, product, opts = {})', start);
assert.ok(start > 0 && stop > start, 'production local stock selection block must exist');
const ctlStart = html.indexOf('let ctlLoadSerial = 0;');
const ctlEnd = html.indexOf('window.addEventListener("beforeunload"', ctlStart);
assert.ok(ctlStart > 0 && ctlEnd > ctlStart, 'controller-image file selection block must exist');
const source = html.slice(ctlStart, ctlEnd) + '\n' + html.slice(start, stop);

function picker({ digest } = {}) {
  const nodes = {};
  const node = () => ({
    checked: false, disabled: false, value: 'previous', textContent: '', handlers: {},
    addEventListener(event, fn) { this.handlers[event] = fn; },
    classList: { add() {}, remove() {} },
  });
  const dom = new Proxy(nodes, { get(t, p) { return (t[p] ||= node()); } });
  const events = [];
  const api = runInNewContext(`(() => {
    let stock = null, ctl = null, writing = false, lastId = null;
    const $ = id => dom[id];
    const sayK = (code, suffix) => events.push({ code, suffix });
    const STOCK_SHA256_FM1 = 'stock-reference';
    const productOf = raw => raw[0] === 1 ? 'SMK-37 Pro_9001000'
      : raw[0] === 2 ? 'SMK-37 Elite_9001000'
      : raw[0] === 3 ? 'FM-1_9001000' : 'Unrelated_9001000';
    const sha256Hex = raw => digest(raw);
    const sameKeyboard = (from, to) => (/^FM-1/i.test(from) === /^FM-1/i.test(to));
    const logicalImage = raw => raw;
    const ctlProblem = raw => raw[0] === 8 || raw[0] === 9 ? null : "not-controller-image";
    ${source}
    return {
      stock: () => stock, ctl: () => ctl, state: () => ({ writing, lastId }),
      connect: model => { lastId = { model, text: model }; },
      writing: value => { writing = value; },
    };
  })()`, { dom, events, digest: digest || (async () => 'not-stock') });
  const input = file => {
    dom.stockfile.value = 'selected.fwsc';
    return dom.stockfile.handlers.change({
      target: {
        files: [file],
        get value() { return dom.stockfile.value; },
        set value(v) { dom.stockfile.value = v; },
      },
    });
  };
  const ctlInput = file => {
    dom.ctlfile.value = 'selected.img';
    return dom.ctlfile.handlers.change({
      target: {
        files: [file],
        get value() { return dom.ctlfile.value; },
        set value(v) { dom.ctlfile.value = v; },
      },
    });
  };
  const drop = file => dom.stockdrop.handlers.drop({
    preventDefault() {},
    dataTransfer: { files: [file] },
  });
  return { dom, api, events, input, ctlInput, drop };
}

const file = id => ({ arrayBuffer: async () => Uint8Array.of(id).buffer });
function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
async function caseRun(name, fn) {
  await fn();
  console.log('PASS', name);
}

await caseRun('last selected file wins when an earlier read resolves late', async () => {
  const p = picker();
  const slow = deferred();
  const a = p.input({ arrayBuffer: () => slow.promise });
  const b = p.input(file(2));
  await b;
  assert.equal(p.api.stock()?.product, 'SMK-37 Elite_9001000');
  slow.resolve(Uint8Array.of(1).buffer);
  await a;
  assert.equal(p.api.stock()?.product, 'SMK-37 Elite_9001000');
});

await caseRun('drag/drop wins over an earlier file chooser', async () => {
  const p = picker();
  const slow = deferred();
  const a = p.input({ arrayBuffer: () => slow.promise });
  await p.drop(file(2));
  slow.resolve(Uint8Array.of(1).buffer);
  await a;
  assert.equal(p.api.stock()?.product, 'SMK-37 Elite_9001000');
});

await caseRun('late SHA calculation cannot replace latest selection', async () => {
  const slow = deferred();
  const p = picker({
    digest: raw => new Uint8Array(raw)[0] === 1 ? slow.promise : Promise.resolve('not-stock'),
  });
  const a = p.input(file(1));
  await Promise.resolve();
  const b = p.input(file(2));
  await b;
  slow.resolve('not-stock');
  await a;
  assert.equal(p.api.stock()?.product, 'SMK-37 Elite_9001000');
});

await caseRun('new selection immediately clears consent and disables Install', async () => {
  const p = picker();
  await p.input(file(1));
  p.dom.stockconfirm.checked = true;
  p.dom.stockconfirm.handlers.change();
  assert.equal(p.dom.stockgo.disabled, false);
  const pending = deferred();
  const first = p.input({ arrayBuffer: () => pending.promise });
  assert.equal(p.api.stock(), null);
  assert.equal(p.dom.stockconfirm.checked, false);
  assert.equal(p.dom.stockgo.disabled, true);
  pending.resolve(Uint8Array.of(2).buffer);
  await first;
  assert.equal(p.dom.stockgo.disabled, true, 'new build must require fresh consent');
  assert.equal(p.api.stock()?.product, 'SMK-37 Elite_9001000');
  assert.equal(p.dom.stockfile.value, '', 'allow choosing same file again');
});

await caseRun('stale read rejection does not affect later valid selection', async () => {
  const p = picker();
  const slow = deferred();
  const a = p.input({ arrayBuffer: () => slow.promise });
  await p.input(file(2));
  slow.reject(new Error('delayed failed read'));
  await a;
  assert.equal(p.api.stock()?.product, 'SMK-37 Elite_9001000');
  assert.equal(p.events.at(-1)?.code, 'stockok');
});

await caseRun('active read rejection is handled and reported', async () => {
  const p = picker();
  await p.input({ arrayBuffer: () => Promise.reject(new Error('cannot read')) });
  assert.equal(p.api.stock(), null);
  assert.equal(p.dom.stockgo.disabled, true);
  assert.equal(p.events.at(-1)?.code, 'stockloadfail');
});

await caseRun('invalid and wrong-family packages cannot be installed', async () => {
  const p = picker();
  await p.input(file(1));
  p.dom.stockconfirm.checked = true;
  p.dom.stockconfirm.handlers.change();
  await p.input(file(0));
  assert.equal(p.api.stock(), null);
  assert.equal(p.dom.stockgo.disabled, true);
  p.api.connect('FM-1');
  await p.input(file(1));
  assert.equal(p.api.stock(), null);
  assert.equal(p.dom.stockgo.disabled, true);
  assert.equal(p.events.at(-1)?.code, 'model');
});

await caseRun('last controller image wins with overlapping reads', async () => {
  const p = picker();
  const slow = deferred();
  const a = p.ctlInput({ arrayBuffer: () => slow.promise });
  await p.ctlInput(file(9));
  assert.equal(p.api.ctl()?.[0], 9);
  slow.resolve(Uint8Array.of(8).buffer);
  await a;
  assert.equal(p.api.ctl()?.[0], 9);
  assert.equal(p.dom.ctlfile.value, '', 'allow reselecting same controller image');
});

await caseRun('new controller choice invalidates earlier controller', async () => {
  const p = picker();
  await p.ctlInput(file(8));
  await p.ctlInput(file(0));
  assert.equal(p.api.ctl(), null);
  assert.equal(p.events.at(-1)?.code, 'ctlbad');
});

await caseRun('failed controller read is handled, not an unhandled rejection', async () => {
  const p = picker();
  await p.ctlInput({ arrayBuffer: () => Promise.reject(new Error('cannot read')) });
  assert.equal(p.api.ctl(), null);
  assert.equal(p.events.at(-1)?.code, 'ctlreadfail');
});

assert.ok(html.includes('ctlreading:'), 'must provide controller loading message');
assert.ok(html.includes('ctlreadfail:'), 'must provide controller read failure message');
assert.ok(html.includes('stockloading:'), 'must provide readable loading message in both language dictionaries');
assert.ok(html.includes('stockloadfail:'), 'must provide readable read failure message');
console.log('local .fwsc selection regressions passed');

/* SPDX-License-Identifier: GPL-3.0-only */
/* Production integration checks adapted from the reviewed PR150 suite. Routing runs through
 * the same fixture as smc_ui; hardware is replaced by a bounded output recorder.
 * Physical Pause bytes are retained-capture evidence for this owner preset.
 * These host tests establish dispatch/output bytes, never physical LED identity. */
#include <stdint.h>
#include <string.h>
static unsigned send_count, led_count, led_transport_count;
static uint8_t sent[256][3];
int plat_ble_smc_send(const uint8_t *m, uint8_t n)
{
    if (send_count < 256 && n == 3) memcpy(sent[send_count], m, 3);
    send_count++;
    if (n == 3 && m[0] == 0x90) {
        led_count++;
        if (m[1] >= 0x5D && m[1] <= 0x5F) led_transport_count++;
    }
    return 1;
}
#define SMC_UI_SEND_IMPLEMENTED 1
#define SMC_UI_MAIN smc_ui_baseline_main
#include "smc_ui_test.c"

/* Baseline replay alone supplies an absent-operation stub, so it compiles and
 * reaches the new target assertion. A compiler error never counts as negative. */
#ifdef SMC_LOCK_BASELINE
static int smc_lock_toggle(void) { return 1; }
static int smc_lock_button(int pressed) { (void)pressed; return 0; }
#endif

static void navigate(int view, int part)
{
    ui.part = (uint8_t)part;
    ui.mixsel = (uint8_t)part;
    set_view(view);
    build_pages();
    smc_ui_cancel();
}
static void reset_output(void)
{
    send_count = led_count = led_transport_count = 0;
    memset(sent, 0, sizeof sent);
}
static void navigation_unchanged(screen_state_t before)
{
    /* Parked navigation may show its intentional locked notification. */
    screen_state_t after = screen_state();
    memcpy(before.msg, after.msg, sizeof before.msg);
    before.msg_until = after.msg_until;
    unchanged(before);
}
static void test_drum_lock(void)
{
    for (int kit = 0; kit < 2; kit++) for (int bank = 0; bank < 2; bank++) {
        pref_t f[8], k[8];
        setup(V_SEQ, kit); ui.sel[kit] = (uint8_t)(bank * 8); build_pages();
        for (int i = 0; i < 8; i++) { f[i] = smc_target(i); k[i] = smc_knob_target(i); }
        CHECK(smc_lock_toggle());
        navigate(V_PART, kit ? PART_909 : PART_808);
        ui.sel[kit] = (uint8_t)(bank ? 0 : 8); build_pages();
        for (int i = 0; i < 8; i++) {
            CHECK(smc_same(f[i], smc_target(i))); /* original source fails here */
            CHECK(smc_same(k[i], smc_knob_target(i)));
            if (bank && i >= 3) CHECK(smc_target(i).kind == R_NONE);
        }
        pref_t r = k[0];
        pref_set(r, 48); int before = pref_get(r);
        screen_state_t ui_before = screen_state();
        knob(0, 1); CHECK(pref_get(r) > before); unchanged(ui_before);
        int muted = track_muted(kit, bank * 8);
        int foreign = track_muted(!kit, 0);
        message(0x90, 16, 127);
        CHECK(track_muted(kit, bank * 8) != muted);
        CHECK(track_muted(!kit, 0) == foreign);
        message(0x90, 8, 127);
        CHECK(smc.drum_solo[kit] & (1u << (bank * 8)));
        message(0x90, 8, 127); /* repeated held key cannot redirect */
        CHECK(smc.drum_solo[kit] == (1u << (bank * 8)));
        message(0x80, 8, 0); CHECK(!smc_project_active());
